// Sync (non-batched) subscribers must be notified in the order they
// were created, while batched subscribers rely on being notified in
// reverse order so that they are flushed in creation order. Collect
// the sync subscribers during the reverse traversal and notify them
// in reverse afterwards.
let syncSubs: Subscriber[] | undefined
for (let link = dep.subs; link; link = link.prevSub) {
  const sub = link.sub
  if (sub.flags & EffectFlags.NO_BATCH) {
    ;(syncSubs || (syncSubs = [])).push(sub)
  } else {
    sub.notify()
  }
}
if (syncSubs) {
  for (let i = syncSubs.length - 1; i >= 0; i--) {
    syncSubs[i].notify()
  }
}

