import { computed, ref } from '@vue/reactivity'
import { watch } from '../src/apiWatch'

describe('tmp sync order', () => {
  it('ref', () => {
    const n = ref(0)
    const out: number[] = []
    for (let i = 0; i < 5; i++) {
      watch(n, () => out.push(i), { flush: 'sync' })
    }
    n.value++
    expect(out).toEqual([0, 1, 2, 3, 4])
  })

  it('computed', () => {
    const n = ref(0)
    const c = computed(() => n.value)
    const out: number[] = []
    for (let i = 0; i < 5; i++) {
      watch(c, () => out.push(i), { flush: 'sync' })
    }
    n.value++
    expect(out).toEqual([0, 1, 2, 3, 4])
  })
})

